service.method:

DELETE FROM 
	SGRFT 
WHERE 
	GRID_ID = ${GRID_ID}
AND HOUSE_CODE = ${HOUSE_CODE}


INSERT INTO SGRFT
(
	  HOUSE_CODE
	, GRID_ID
	, CODE
	, ADD_USER_ID
	, ADD_DATE
	, ADD_TIME
	, CHANGE_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, COL_TYPE
	, NOT_NULL
	, COL_FORMAT
	, COL_ALIGN
	, COL_SORT
	, COL_COLOR
	, COL_SEQ
)
VALUES
(
	  ${HOUSE_CODE}
	, ${GRID_ID}
	, ${CODE}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${COL_TYPE}
	, ${NOT_NULL}
	, ${COL_FORMAT}
	, ${COL_ALIGN}
	, ${COL_SORT}
	, ${COL_COLOR}
	, ${COL_SEQ}
)


DELETE FROM
	SLANG
WHERE
	HOUSE_CODE = ${HOUSE_CODE}
AND SCREEN_ID = ${GRID_ID}
AND LANGUAGE = ${session.LANGUAGE}
AND CODE = ${CODE}


INSERT INTO SLANG
(
	  HOUSE_CODE
	, SCREEN_ID
	, LANGUAGE
	, CODE
	, CONTENTS
	, ADD_USER_ID
	, ADD_DATE
	, ADD_TIME
	, CHANGE_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, DEL_FLAG
	, GRID_WIDTH
)
VALUES
(
	  ${HOUSE_CODE}
	, ${GRID_ID}
	, ${session.LANGUAGE}
	, ${CODE}
	, ${CONTENTS}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, 'N'
	, ${COL_WIDTH}
)
